function render(){const page=document.getElementById('page');if(!page||!current)return;const d=defs[current];if(loading){page.innerHTML=shell(d,tabs(d)+'<p class="muted">جاري تحميل البيانات الفعلية…</p>');return}if(error){page.innerHTML=shell(d,tabs(d)+'<div class="empty-state">'+esc(error)+'</div>');bind();return}page.innerHTML=tab==='overview'?overview(d):body(d);bind()}
function bind(){document.querySelectorAll('[data-op-tab]').forEach(b=>b.onclick=async()=>{tab=b.dataset.opTab;if(current==='MantiGO والنقل'&&tab==='open'){const r=await sb.rpc('list_open_mantigo_rides_backend',{p_user_id:user.id});rows.mantigo_open=r.data||[]}render()});document.querySelectorAll('[data-mg-vehicle]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-mg-vehicle]').forEach(x=>x.classList.remove('active'));b.classList.add('active');const v=document.getElementById('mgVehicle');if(v)v.value=b.dataset.mgVehicle});document.querySelector('[data-mg-location]')?.addEventListener('click',async()=>{const b=document.querySelector('[data-mg-location]');if(!navigator.geolocation)return alert('المتصفح لا يدعم تحديد الموقع.');b.disabled=true;b.textContent='جاري تحديد الموقع…';const p=await mgGetCurrentPosition();b.disabled=false;b.textContent='⌖ موقعي';if(!p)return alert('تعذر تحديد موقعك. اسمح للموقع من إعدادات المتصفح أو اكتب نقطة الانطلاق يدويًا.');const input=document.getElementById('mgPickup');if(input){input.value='موقعي الحالي';input.dataset.lat=p.lat;input.dataset.lon=p.lon}});document.getElementById('save-lead')?.addEventListener('click',saveLead);document.querySelectorAll('[data-job-apply]').forEach(b=>b.onclick=()=>applyJob(b.dataset.jobApply));document.querySelectorAll('[data-edu-request]').forEach(b=>b.onclick=()=>createEducationRequest(b.dataset.eduRequest,b.dataset.eduType,b.dataset.eduName));document.querySelectorAll('[data-medical-book]').forEach(b=>b.onclick=()=>medicalBook(b.dataset.medicalBook));document.getElementById('mgCreateRide')?.addEventListener('click',mgCreateRide);document.getElementById('mgSubmitBid')?.addEventListener('click',mgSubmitBid);document.querySelectorAll('[data-mg-bid]').forEach(b=>b.onclick=()=>{const id=b.dataset.mgBid;const box=b.closest('.card');box.insertAdjacentHTML('beforeend',mantigoBidForm(id));bind()});document.querySelectorAll('[data-mg-accept]').forEach(b=>b.onclick=()=>mgAccept(b.dataset.mgAccept,b.dataset.mgRide));document.querySelectorAll('[data-mg-rate]').forEach(b=>b.onclick=()=>mgRate(b.dataset.mgRate));document.querySelectorAll('[data-mg-cancel]').forEach(b=>b.onclick=()=>mgTransition(b.dataset.mgCancel,'CANCELLED'));document.querySelectorAll('[data-mg-status]').forEach(b=>b.onclick=()=>mgTransition(b.dataset.mgRide,b.dataset.mgStatus));document.querySelectorAll('[data-mg-presence]').forEach(b=>b.onclick=()=>mgSetPresence(b.dataset.mgPresence));document.getElementById('mgApplyCaptain')?.addEventListener('click',mgApplyCaptain);document.querySelectorAll('[data-mg-cash-pay]').forEach(b=>b.onclick=()=>mgCashPay(b.dataset.mgCashPay));document.querySelectorAll('[data-mg-card-pay]').forEach(b=>b.onclick=()=>mgCardPay(b.dataset.mgCardPay))}
function observe(){const n=document.querySelector('.breadcrumb')?.textContent?.trim()||'';const d=defs[n];if(d&&!current){current=n;tab=d.key==='MANTIGO'?'request':'overview';load(d)}if(!d)current=null}new MutationObserver(observe).observe(document.body,{childList:true,subtree:true});setInterval(observe,800);
